# ── AWS S3 ────────────────────────────────────────────────────────────────────
# Disabled by default for local dev — no AWS credentials needed.
# To test real S3 uploads locally, export these env vars and restart:
#
#   export AWS_S3_ENABLED=true
#   export AWS_ACCESS_KEY_ID=your_key
#   export AWS_SECRET_ACCESS_KEY=your_secret
#   export AWS_S3_BUCKET_NAME=qrapp-menu-images   # optional, uses default
#   export AWS_S3_REGION=us-east-1               # optional, uses default
#
aws:
  s3:
    enabled: ${AWS_S3_ENABLED:true}
    bucket-name: ${AWS_S3_BUCKET_NAME:broandbro-menu-images-dev}
    region: ${AWS_S3_REGION:us-east-1}
    access-key: ${AWS_ACCESS_KEY_ID:AKIA34EPRSL6ICFWRYHI}
    secret-key: ${AWS_SECRET_ACCESS_KEY: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}

# ── V1 Recommended Bundle Pricing ────────────────────────────────────────────
# savings = min( originalPrice × discount-percent%, max-discount-rupees )
# Change these values without touching code; restart the server to apply.
app:
  bundle:
    discount-percent: 10       # 10 % of the recommended-items total
    max-discount-rupees: 50    # ₹50 absolute cap
    max-items: 3               # maximum items to include in one bundle

  # ── Complete Your Meal Pricing ───────────────────────────────────────────
  # savings = min( mealTotal × discount-percent%, max-discount-rupees )
  meal:
    discount-percent: 10       # 10 % of the meal items total
    max-discount-rupees: 50    # ₹50 absolute cap

